function buildSurfaces(){const mat=material('#ffffff').clone();mat.vertexColors=true;mat.map=mat.map.clone();mat.map.wrapS=mat.map.wrapT=THREE.RepeatWrapping;mat.map.needsUpdate=true;for(const chunk of surfaceChunks.values()){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(chunk.positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(chunk.normals,3));g.setAttribute('color',new THREE.Float32BufferAttribute(chunk.colors,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(chunk.uvs,2));g.setIndex(chunk.indices);g.computeBoundingSphere();addToDistrict(new THREE.Mesh(g,mat),chunk.region);}}
