let lastSwimmingNotice=-10;
function waterBlocked(x,z){return locationZone==='edmonton'&&((river(x,z)&&!bridge(x,z))||decorativeWater.some(a=>Math.abs(x-a.x)<a.w/2+10&&Math.abs(z-a.z)<a.d/2+10));}
function swimmingNotice(){if(time-lastSwimmingNotice<3)return;lastSwimmingNotice=time;world.notify('I’m still working on my swimming skills! Let’s use a bridge.');}
function isBlocked(x,z){if(locationZone==='interior'){const o=roomOrigins[room],l=ROOM_LAYOUT[room];return Math.abs(x-o.x)>l.halfX-13||Math.abs(z-o.z)>l.halfZ+18;}if(locationZone==='toronto'){if(x<3700||x>5300||Math.abs(z)>800)return true;}else if(Math.abs(x)>1450||Math.abs(z)>1450)return true;return colliders.some(c=>Math.abs(x-c.x)<c.w&&Math.abs(z-c.z)<c.d)||(locationZone==='edmonton'&&((river(x,z)&&!bridge(x,z))||decorativeWater.some(a=>Math.abs(x-a.x)<a.w/2+10&&Math.abs(z-a.z)<a.d/2+10)));}
function move(dx,dz){const beforeX=position.x,beforeZ=position.z;const attemptedWater=(Math.abs(dx)>.001&&waterBlocked(position.x+dx,position.z))||(Math.abs(dz)>.001&&waterBlocked(position.x,position.z+dz));if(attemptedWater){swimmingNotice();stopWalking();walkTarget=null;trackVelocity.forward=trackVelocity.side=0;}if(!isBlocked(position.x+dx,position.z))position.x+=dx;if(!isBlocked(position.x,position.z+dz))position.z+=dz;if(cruise&&Math.hypot(dx,dz)>.01&&Math.hypot(position.x-beforeX,position.z-beforeZ)<.001)stopWalking();}
function showPrompt(){prompt.hidden=true;}
function switchView(){lastHud=-1;hudValues.clear();stopWalking();cameraSnap=true;hoverPointer=null;if(flight||elevator){world.notify('Journey in progress. The map returns when you arrive.');return;}if(!initialized){try{build();}catch(error){window.fppActive=false;console.error(error);world.notify('3D graphics could not start. The overhead map is ready.');return;}}active=!active;window.fppActive=active;document.body.classList.toggle('fpp-mode',active);canvas.hidden=!active;document.querySelector('#world').hidden=active;document.querySelector('#crosshair').hidden=!active;toggle.textContent=active?'OVERHEAD MAP':'ENTER FIRST PERSON';document.querySelector('#control-hint').textContent=active?'Tap Walk to move · Swipe to steer · Tap Stop to stop':'Click to walk · F for first person';keys.clear();cancelAnimationFrame(frameId);
 if(active){if(room==='lift'){document.querySelector('#lift-panel').hidden=false;}else if(room){showChapter(room);}if(locationZone==='edmonton'&&position.x===0&&position.z===0)position.z=550;previous=performance.now();frameId=requestAnimationFrame(frame);world.notify('Tap Walk once to move. Swipe to steer. Tap Stop to stop.');}else{closeRoomPanel();if(document.pointerLockElement)document.exitPointerLock();}showPrompt();}
