toggle.addEventListener('click',switchView);window.addEventListener('keydown',e=>{if(e.metaKey||e.ctrlKey||e.altKey)return;const k=e.key.toLowerCase();if(k==='escape'&&!document.querySelector('#npc-dialogue').hidden){document.querySelector('#npc-close').click();return;}if(document.querySelector('#art-viewer').open){if(k==='escape')document.querySelector('#art-viewer').close();return;}if(world.dialog.open){if(k==='escape'){e.preventDefault();world.dialog.close();}return;}if(k==='f'&&!e.repeat){e.preventDefault();tour?.stop();switchView();return;}if(!active)return;if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','shift','e'].includes(k)){e.preventDefault();manualIntent();keys.add(k);if(k===' '&&lift===0&&!flight&&!elevator)vertical=235;if(k==='e'&&!e.repeat)interact();}if(k==='escape'){tour?.stop();clearMotion();if(room)exitRoom();}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{tour?.pause();clearMotion();});document.addEventListener('visibilitychange',()=>{clearMotion();if(document.hidden)tour?.pause();previous=performance.now();});
