window.firstPerson={switchView,get active(){return active;},get ready(){return initialized;},get position(){return {...position};},get camera(){return camera;},get near(){return near;},get renderer(){return renderer;},teleport(x,z){position.x=x;position.z=z;},get lift(){return lift;},look,startJourney,enterBuilding,exitRoom,takeFlight,travelTo,get room(){return room;},get zone(){return locationZone;},get flying(){return !!flight;},get entered(){return [...entered];},get door(){return currentDoor();},get trackVelocity(){return {...trackVelocity};},get cruising(){return cruise;},get frameAverage(){return frameAverage;},enterLift,rideLift,leaveLift,get ridingLift(){return !!elevator;},get elevatorFloor(){return elevatorFloor;},get studentCount(){return experienceScenes?.studentCount||0;},get actors(){return experienceScenes?.actors;},get trailVisible(){return trailOn&&trailMesh?.visible;},get inWater(){return waterBlocked(position.x,position.z);},get npcCounts(){return {students:experienceScenes.npcs.filter(n=>n.room==='university').length,colleagues:experienceScenes.npcs.filter(n=>n.room==='td').length};},get npcs(){return experienceScenes.npcs;},get workstations(){return experienceScenes.workstations;},get nightLights(){return {fixtures:lightFixtures.length,active:poolLights.filter(l=>l.intensity>0).length,glow:nightObjects.filter(o=>o.material?.isShaderMaterial&&o.visible).length};},get guides(){return experienceScenes.guides;},get trailPoints(){return activeTrailPoints.map(p=>[...p]);},get tour(){return tour;},get aircraft(){return {edmonton:airplane.position.toArray(),toronto:returnAirplane.position.toArray(),edmontonParking,torontoParking,flight:flight?{back:flight.back,phase:flight.phase,sample:flight.sample,elapsed:time-flight.start,duration:flight.duration,position:flight.plane.position.toArray(),target:flight.to}:null};},get landmarks(){return buildings.landmarks.map(a=>({...a}));}};
